2.  * Time & locale helpers — pure functions, safe for both server (Astro
3.  * frontmatter) and client (script tags).  All date inputs are UTC ISO strings.
4.  *
5.  * Consolidates the former time-format.ts into a single module.
6.  */
7. 
8. import { RACE_TYPES } from './sessions';
9. 
10. // ── Types ───────────────────────────────────────────────────────────────────
11. 
12. export type LocalTimeFormat = 'datetime' | 'time' | 'time-short' | 'date' | 'weekday-time';
13. 
14. // ── Country flag ────────────────────────────────────────────────────────────
15. 
16. /** Emoji flag from ISO 3166-1 alpha-2 code. Returns '' for invalid input. */
17. export function countryFlag(code: string): string {
18.   if (!code || code.length !== 2) return '';
19.   const upper = code.toUpperCase();
20.   if (!/^[A-Z]{2}$/.test(upper)) return '';
21.   const base = 0x1F1E6 - 0x41;
22.   return String.fromCodePoint(upper.charCodeAt(0) + base, upper.charCodeAt(1) + base);
23. }
24. 
25. // ── Formatting ──────────────────────────────────────────────────────────────
26. 
27. function getFormatOptions(format: LocalTimeFormat): Intl.DateTimeFormatOptions {
28.   switch (format) {
29.     case 'date':
30.       return { month: 'short', day: 'numeric' };
31.     case 'time':
32.     case 'time-short':
33.       return { hour: '2-digit', minute: '2-digit', hour12: false };
34.     case 'weekday-time':
35.       return { weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false };
36.     case 'datetime':
37.     default:
38.       return { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false };
39.   }
40. }
41. 
42. /** Format a UTC string in the user's local timezone. */
43. export function formatLocalValue(utc: string, format: LocalTimeFormat = 'datetime'): string {
44.   return new Date(utc).toLocaleString(undefined, getFormatOptions(format));
45. }
46. 
47. /** Format a UTC string showing the UTC value (with "UTC" suffix). */
48. export function formatUtcValue(utc: string, format: LocalTimeFormat = 'datetime'): string {
49.   return `${new Date(utc).toLocaleString('en', {
50.     ...getFormatOptions(format),
51.     timeZone: 'UTC',
52.   })} UTC`;
53. }
54. 
55. /** Shorthand: local time-short format (HH:MM). */
56. export function formatLocalTime(utc: string): string {
57.   return formatLocalValue(utc, 'time-short');
58. }
59. 
60. /** Shorthand: local datetime format. */
61. export function formatLocalDatetime(utc: string): string {
62.   return formatLocalValue(utc, 'datetime');
63. }
64. 
65. /** Human-readable date range (e.g. "Jun 7–9" or "Jun 28 – Jul 1"). */
66. export function formatDateRange(dateStart: string, dateEnd: string): string {
67.   const start = new Date(dateStart + 'T12:00:00Z');
68.   const end = new Date(dateEnd + 'T12:00:00Z');
69.   const fmt = new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric' });
70.   if (dateStart === dateEnd) return fmt.format(start);
71.   if (start.getMonth() === end.getMonth()) return `${fmt.format(start)}–${end.getDate()}`;
72.   return `${fmt.format(start)} – ${fmt.format(end)}`;
73. }
74. 
75. // ── Date predicates ─────────────────────────────────────────────────────────
76. 
77. export interface SessionLike {
78.   type: string;
79.   startTimeUTC: string;
80. }
81. 
82. /** Latest real session start time for an event, if one exists. */
83. export function getEventLastSessionTime(sessions: SessionLike[] = []): Date | null {
84.   const validTimes = sessions
85.     .map(session => session.startTimeUTC)
86.     .filter(utc => !isPlaceholderTime(utc))
87.     .map(utc => new Date(utc))
88.     .filter(date => !Number.isNaN(date.getTime()));
89. 
90.   if (validTimes.length === 0) return null;
91.   return new Date(Math.max(...validTimes.map(date => date.getTime())));
92. }
93. 
94. /** True if an event has no remaining real sessions. */
95. export function isPastEvent(dateEnd: string, sessions: SessionLike[] = []): boolean {
96.   const lastSession = getEventLastSessionTime(sessions);
97.   if (lastSession) return lastSession < new Date();
98.   return new Date(dateEnd + 'T23:59:59Z') < new Date();
99. }
100. 
101. /** True if the timestamp is a placeholder (year 1900). */
102. export function isPlaceholderTime(utc: string): boolean {
103.   return !utc || utc.startsWith('1900-');
104. }
105. 
106. // ── Session helpers ─────────────────────────────────────────────────────────
107. 
108. /** Get the main race session from an event's sessions array.
109.  * Returns the LAST race-type session so that on sprint weekends the main Race
110.  * (Sunday) is preferred over the Sprint (Saturday). Falls back to the last
111.  * session overall if no race-type session exists. */
112. export function getRaceSession(sessions: { type: string; startTimeUTC: string }[]): { type: string; startTimeUTC: string } | undefined {
113.   const raceSessions = sessions.filter(s => RACE_TYPES.has(s.type));
114.   return raceSessions[raceSessions.length - 1] ?? sessions[sessions.length - 1];
115. }
116.

