2.  * ICS calendar file generation — pure client-side.
3.  * Generates RFC 5545 compliant .ics files from event data.
4.  */
5. 
6. import broadcasts from '../../data/gold/broadcasts.json';
7. import { getSeriesMeta } from './series';
8. import { getSessionDurationMinutes } from './sessions';
9. import type { RaceEvent, RaceSession } from './types';
10. 
11. type IcsSession = RaceSession;
12. type IcsEvent = Pick<RaceEvent, 'id' | 'seriesId' | 'eventName' | 'circuit' | 'sessions'>;
13. 
14. type BroadcastEntry = {
15.   channel: string;
16.   type: string;
17.   note?: string;
18. };
19. 
20. type BroadcastRegionMap = Record<string, BroadcastEntry[]>;
21. 
22. const BROADCASTS = broadcasts as {
23.   regions?: Record<string, { label: string; flag?: string }>;
24.   series?: Record<string, BroadcastRegionMap>;
25. };
26. 
27. const SERIES_EMOJI: Record<string, string> = {
28.   f1: '🔴',
29.   f2: '🔺',
30.   f3: '🔻',
31.   fe: '🔵',
32.   indycar: '🟡',
33.   nascar: '🟦',
34.   motogp: '🟠',
35.   moto2: '🟧',
36.   moto3: '🟨',
37.   wec: '🟢',
38.   wsbk: '⚫',
39.   imsa: '🟩',
40.   dtm: '🟣',
41.   nls: '🟤',
42.   superformula: '⚪',
43.   iomtt: '🏍️',
44. };
45. 
46. function toIcsDate(utc: string): string {
47.   return utc.replace(/[-:]/g, '').replace(/\.\d+/, '').replace('T', 'T').slice(0, 15) + 'Z';
48. }
49. 
50. function addMinutes(utc: string, minutes: number): string {
51.   const d = new Date(utc);
52.   d.setMinutes(d.getMinutes() + minutes);
53.   return d.toISOString();
54. }
55. 
56. function escapeIcs(str: string): string {
57.   return str.replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\n/g, '\\n');
58. }
59. 
60. function getSeriesSummaryPrefix(seriesId: string): string {
61.   const meta = getSeriesMeta(seriesId);
62. 
63.   return `${SERIES_EMOJI[seriesId] ?? '🏁'} ${meta.shortLabel}`;
64. }
65. 
66. function formatBroadcastLine(regionId: string, entries: BroadcastEntry[]): string {
67.   const region = BROADCASTS.regions?.[regionId];
68.   const prefix = region?.flag ? `${region.flag} ${regionId}` : regionId;
69.   const channels = entries.map(entry => {
70.     const suffix = entry.note ? `, ${entry.note}` : '';
71.     return `${entry.channel} (${entry.type}${suffix})`;
72.   }).join(', ');
73. 
74.   return `${prefix}: ${channels}`;
75. }
76. 
77. function getDescription(event: IcsEvent, session: IcsSession): string {
78.   const meta = getSeriesMeta(event.seriesId);
79.   const lines = [
80.     `${meta.label}`,
81.     `Session: ${session.type}`,
82.     `Circuit: ${event.circuit.name}`,
83.   ];
84. 
85.   const location = [event.circuit.city, event.circuit.country].filter(Boolean).join(', ');
86.   if (location) lines.push(`Location: ${location}`);
87. 
88.   const regionEntries = Object.entries(BROADCASTS.series?.[event.seriesId] ?? {})
89.     .filter(([, entries]) => entries.length > 0)
90.     .map(([regionId, entries]) => formatBroadcastLine(regionId, entries));
91. 
92.   if (regionEntries.length > 0) {
93.     lines.push('', 'Broadcasts:', ...regionEntries);
94.   }
95. 
96.   return lines.join('\n');
97. }
98. 
99. function makeVEvent(event: IcsEvent, session: IcsSession): string {
100.   const dur = getSessionDurationMinutes(session.type);
101.   const location = [event.circuit.name, event.circuit.city, event.circuit.country].filter(Boolean).join(', ');
102.   const uid = `${event.id}-${session.type.replace(/\s+/g, '')}@racetrack`;
103. 
104.   return [
105.     'BEGIN:VEVENT',
106.     `UID:${uid}`,
107.     `DTSTART:${toIcsDate(session.startTimeUTC)}`,
108.     `DTEND:${toIcsDate(addMinutes(session.startTimeUTC, dur))}`,
109.     `SUMMARY:${escapeIcs(`${getSeriesSummaryPrefix(event.seriesId)} ${event.eventName} - ${session.type} @ ${event.circuit.name}`)}`,
110.     `LOCATION:${escapeIcs(location)}`,
111.     `DESCRIPTION:${escapeIcs(getDescription(event, session))}`,
112.     'END:VEVENT',
113.   ].join('\r\n');
114. }
115. 
116. function makeCalendar(name: string, events: IcsEvent[]): string {
117.   const vEvents = events.flatMap(ev =>
118.     ev.sessions
119.       .filter(s => !s.startTimeUTC.startsWith('1900-'))
120.       .map(s => makeVEvent(ev, s))
121.   );
122. 
123.   return [
124.     'BEGIN:VCALENDAR',
125.     'VERSION:2.0',
126.     'PRODID:-//RaceTrack//Motorsport Calendar//EN',
127.     `X-WR-CALNAME:${escapeIcs(name)}`,
128.     'CALSCALE:GREGORIAN',
129.     'METHOD:PUBLISH',
130.     ...vEvents,
131.     'END:VCALENDAR',
132.   ].join('\r\n');
133. }
134. 
135. /** Download an .ics file in the browser. */
136. export function downloadIcs(filename: string, content: string): void {
137.   const blob = new Blob([content], { type: 'text/calendar;charset=utf-8' });
138.   const url = URL.createObjectURL(blob);
139.   const a = document.createElement('a');
140.   a.href = url;
141.   a.download = filename;
142.   document.body.appendChild(a);
143.   a.click();
144.   document.body.removeChild(a);
145.   URL.revokeObjectURL(url);
146. }
147. 
148. /** Export a single event's race session as .ics. */
149. export function exportEventIcs(event: IcsEvent): void {
150.   const raceSessions = event.sessions.filter(s =>
151.     !s.startTimeUTC.startsWith('1900-') &&
152.     (s.type === 'Race' || s.type === 'Feature Race')
153.   );
154.   const sessions = raceSessions.length > 0 ? raceSessions : event.sessions.filter(s => !s.startTimeUTC.startsWith('1900-'));
155.   const cal = makeCalendar(event.eventName, [{ ...event, sessions }]);
156.   const safeName = event.eventName.replace(/[^a-zA-Z0-9]+/g, '-').toLowerCase();
157.   downloadIcs(`${safeName}.ics`, cal);
158. }
159. 
160. /** Export multiple events as a single .ics file. */
161. export function exportEventsIcs(name: string, events: IcsEvent[]): void {
162.   const cal = makeCalendar(name, events);
163.   const safeName = name.replace(/[^a-zA-Z0-9]+/g, '-').toLowerCase();
164.   downloadIcs(`${safeName}.ics`, cal);
165. }
