16. /** Emoji flag from ISO 3166-1 alpha-2 code. Returns '' for invalid input. */
17. export function countryFlag(code: string): string {
18.   if (!code || code.length !== 2) return '';
19.   const upper = code.toUpperCase();
20.   if (!/^[A-Z]{2}$/.test(upper)) return '';
21.   const base = 0x1F1E6 - 0x41;
