48. export function formatUtcValue(utc: string, format: LocalTimeFormat = 'datetime'): string {
49.   return `${new Date(utc).toLocaleString('en', {
50.     ...getFormatOptions(format),
51.     timeZone: 'UTC',
52.   })} UTC`;
53. }
54. 
55. /** Shorthand: local time-short format (HH:MM). */
56. export function formatLocalTime(utc: string): string {
57.   return formatLocalValue(utc, 'time-short');
58. }
59. 
60. /** Shorthand: local datetime format. */
61. export function formatLocalDatetime(utc: string): string {
62.   return formatLocalValue(utc, 'datetime');
63. }
