   return `${date.getUTCFullYear()}-${date.getUTCMonth()}-${date.getUTCDate()}`;
 }

 function sessionDayLabelUTC(utc: string) {
   return new Intl.DateTimeFormat('en-US', {
     weekday: 'short',
     timeZone: 'UTC',
   }).format(new Date(utc));
 }

 const sessionGroups = validSessions.reduce<{ dayKey: string; dayLabel: string; sessions: typeof validSessions }[]>((groups, session) => {
   const dayKey = sessionDayKeyUTC(session.startTimeUTC);
   const existing = groups.at(-1);
   if (existing && existing.dayKey === dayKey) {
     existing.sessions.push(session);
     return groups;
   }

   groups.push({
     dayKey,
     dayLabel: sessionDayLabelUTC(session.startTimeUTC),
     sessions: [session],
   });
   return groups;
 }, []);

 // Find next session that hasn't started yet (for "next session" chip)
 const nextSession = validSessions.find(s => new Date(s.startTimeUTC) > new Date());
